-- ============================================
-- LUMA — Thème 7 : MOYEN 2/3 x4 — Comparer deux produits avec un vendeur
-- ============================================


update scenarios set content = '{"characters": {"clerk": "le vendeur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "clerk", "text": "Hi! I see you''re looking at laptops, can I help you compare a few?", "text_fr": "Salut ! Je vois que vous regardez des ordinateurs portables, je peux vous aider à en comparer quelques-uns ?", "choices": [{"text": "Yes, I''m torn between these two models.", "text_fr": "Oui, j''hésite entre ces deux modèles.", "next": "n2"}, {"text": "Actually yes, I need something good for video editing.", "text_fr": "En fait oui, j''ai besoin de quelque chose de bon pour le montage vidéo.", "next": "n2b"}]}, "n2": {"speaker": "clerk", "text": "Good choices! What will you mainly use it for?", "text_fr": "Bons choix ! Vous allez l''utiliser principalement pour quoi ?", "choices": [{"text": "Mostly work — documents, video calls, some light editing.", "text_fr": "Surtout le travail — documents, appels vidéo, un peu de montage léger.", "next": "n3"}]}, "n2b": {"speaker": "clerk", "text": "For video editing, you''ll want strong processing power and a good graphics card.", "text_fr": "Pour le montage vidéo, il vous faudra une puissance de traitement solide et une bonne carte graphique.", "choices": [{"text": "That makes sense — which of these two handles that better?", "text_fr": "Ça se comprend — lequel de ces deux gère mieux ça ?", "next": "n3"}]}, "n3": {"speaker": "clerk", "text": "This one has a faster processor, but this other one has double the storage.", "text_fr": "Celui-ci a un processeur plus rapide, mais cet autre a le double du stockage.", "choices": [{"text": "How much of a difference does the processor speed actually make?", "text_fr": "Quelle différence la vitesse du processeur fait-elle vraiment ?", "next": "n4"}, {"text": "Storage matters a lot to me, I keep a lot of files.", "text_fr": "Le stockage compte beaucoup pour moi, je garde beaucoup de fichiers.", "next": "n4b"}]}, "n4": {"speaker": "clerk", "text": "For everyday tasks, honestly not huge, but for editing, it''s noticeable.", "text_fr": "Pour les tâches quotidiennes, honnêtement pas énorme, mais pour le montage, c''est notable.", "choices": [{"text": "Good to know — what about battery life between the two?", "text_fr": "Bon à savoir — et pour l''autonomie de la batterie entre les deux ?", "next": "n5"}]}, "n4b": {"speaker": "clerk", "text": "Understood, though you could also use an external drive with the other model.", "text_fr": "Compris, même si vous pourriez aussi utiliser un disque externe avec l''autre modèle.", "choices": [{"text": "True, that''s a good point — what about battery life then?", "text_fr": "Vrai, bon point — et pour l''autonomie de la batterie alors ?", "next": "n5"}]}, "n5": {"speaker": "clerk", "text": "The faster processor one actually has slightly better battery life too.", "text_fr": "Celui avec le processeur plus rapide a en fait une autonomie légèrement meilleure aussi.", "choices": [{"text": "That''s a solid point in its favor then.", "text_fr": "C''est un bon point en sa faveur alors.", "next": "n6"}, {"text": "Interesting, what''s the price difference between the two?", "text_fr": "Intéressant, quelle est la différence de prix entre les deux ?", "next": "n6"}]}, "n6": {"speaker": "clerk", "text": "This one is $200 more, but given your needs, I think it''s worth it.", "text_fr": "Celui-ci coûte 200$ de plus, mais vu vos besoins, je pense que ça vaut le coup.", "choices": [{"text": "You make a good case, I think I''ll go with that one.", "text_fr": "Vous plaidez bien votre cause, je pense que je vais prendre celui-là.", "next": "n7"}, {"text": "That''s a bigger gap than I expected — let me think about it a moment.", "text_fr": "C''est un écart plus grand que prévu — laissez-moi y réfléchir un instant.", "next": "n7b"}]}, "n7": {"speaker": "clerk", "text": "Great choice, I think you''ll be really happy with the performance.", "text_fr": "Excellent choix, je pense que vous serez vraiment content de la performance.", "choices": [{"text": "Thank you for breaking it all down so clearly.", "text_fr": "Merci d''avoir tout expliqué si clairement.", "next": "n8"}]}, "n7b": {"speaker": "clerk", "text": "Take your time — happy to answer any more questions while you decide.", "text_fr": "Prenez votre temps — content de répondre à d''autres questions pendant que vous décidez.", "choices": [{"text": "Actually, you''ve convinced me, let''s go with the faster one.", "text_fr": "En fait, vous m''avez convaincu, allons-y avec le plus rapide.", "next": "n8"}]}, "n8": {"speaker": "clerk", "text": "Perfect, let me get that set up for you at checkout.", "text_fr": "Parfait, laissez-moi préparer ça pour vous à la caisse.", "choices": [{"text": "Thank you so much for your help comparing them.", "text_fr": "Merci beaucoup pour votre aide à les comparer.", "next": "end_informed"}]}, "end_informed": {"speaker": "clerk", "text": "Anytime! Enjoy your new laptop.", "text_fr": "Avec plaisir ! Profitez de votre nouvel ordinateur.", "end": true, "ending_label": "Choix éclairé grâce à une comparaison détaillée 💻✅"}}}'::jsonb, is_playable = true
where title = 'Comparer deux produits avec un vendeur'
  and theme_id = (select id from scenario_themes where position = 7 and language_id = (select id from languages where code = 'en'));
